head.b:skin:
:root {
  --bg: #0f1115;
  --bg-2: #141821;
  --glass: rgba(255, 255, 255, 0.08);
  --glass-strong: rgba(255, 255, 255, 0.14);
  --text: #eef2f7;
  --muted: #b2bdcf;
  --primary: #59f0d4;
  --secondary: #7aa2ff;
  --accent: #ff66c4;
  --border: rgba(255, 255, 255, 0.15);
  --shadow: 0 18px 60px rgba(0, 0, 0, 0.4);
  --radius: 26px;
  --radius-sm: 18px;
  --transition: 0.3s ease;
}

[data-theme='light'] {
  --bg: #f4f6fb;
  --bg-2: #ffffff;
  --glass: rgba(255, 255, 255, 0.6);
  --glass-strong: rgba(255, 255, 255, 0.8);
  --text: #121826;
  --muted: #4d5a72;
  --border: rgba(16, 24, 40, 0.12);
  --shadow: 0 18px 60px rgba(16, 24, 40, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: "Cairo", "Inter", system-ui, sans-serif;
  background: radial-gradient(circle at top, #1c2230 0%, #0b0d12 60%);
  color: var(--text);
  min-height: 100vh;
  transition: background var(--transition), color var(--transition);
}

[data-theme='light'] body {
  background: radial-gradient(circle at top, #ffffff 0%, #eef2ff 60%);
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  border-radius: var(--radius-sm);
}

.container {
  width: min(1200px, 92%);
  margin: 0 auto;
}

.glass {
  background: var(--glass);
  border: 1px solid var(--border);
  backdrop-filter: blur(20px);
  box-shadow: var(--shadow);
  border-radius: var(--radius);
}

.glass-strong {
  background: var(--glass-strong);
  border: 1px solid var(--border);
  backdrop-filter: blur(26px);
}

header {
  position: sticky;
  top: 0;
  z-index: 50;
  padding: 24px 0 12px;
  backdrop-filter: blur(24px);
  background: linear-gradient(180deg, rgba(10, 12, 20, 0.95) 0%, rgba(10, 12, 20, 0.4) 100%);
}

[data-theme='light'] header {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.95) 0%, rgba(255, 255, 255, 0.7) 100%);
}

.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 12px;
  font-weight: 800;
  font-size: 20px;
  letter-spacing: 0.5px;
}

.logo img {
  width: 48px;
  height: 48px;
  object-fit: contain;
  border-radius: 16px;
  background: var(--glass-strong);
  padding: 8px;
}

nav ul {
  display: flex;
  gap: 16px;
  list-style: none;
  margin: 0;
  padding: 0;
  flex-wrap: wrap;
}

nav a {
  padding: 10px 18px;
  border-radius: 999px;
  transition: var(--transition);
  font-weight: 600;
  background: transparent;
}

nav a:hover {
  background: var(--glass-strong);
  transform: translateY(-2px);
}

.hero {
  padding: 48px 0 32px;
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  align-items: center;
}

.hero-card {
  padding: 32px;
  position: relative;
  overflow: hidden;
}

.hero-card::after {
  content: "";
  position: absolute;
  inset: -60% 20% auto auto;
  width: 240px;
  height: 240px;
  background: radial-gradient(circle, rgba(255, 102, 196, 0.35), transparent 70%);
  filter: blur(0);
  animation: float 8s ease-in-out infinite;
}

.hero h1 {
  margin: 0 0 16px;
  font-size: clamp(28px, 4vw, 44px);
  font-weight: 800;
  line-height: 1.3;
}

.hero p {
  margin: 0;
  color: var(--muted);
  font-size: 18px;
}

.hero-actions {
  margin-top: 24px;
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
}

.btn {
  padding: 12px 24px;
  border-radius: 999px;
  font-weight: 700;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  color: #0d0f14;
  border: none;
  cursor: pointer;
  transition: var(--transition);
}

.btn.secondary {
  background: var(--glass-strong);
  color: var(--text);
  border: 1px solid var(--border);
}

.btn:hover {
  transform: translateY(-3px) scale(1.01);
}

.grid {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
}

.post-card {
  padding: 18px;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.post-card h3 {
  margin: 0;
  font-size: 20px;
  font-weight: 800;
}

.post-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  color: var(--muted);
  font-size: 14px;
  align-items: center;
}

.post-meta span {
  display: inline-flex;
  gap: 6px;
  align-items: center;
}

.badge {
  padding: 6px 12px;
  border-radius: 999px;
  background: rgba(89, 240, 212, 0.16);
  color: var(--primary);
  font-weight: 600;
  font-size: 12px;
}

.section-title {
  margin: 36px 0 20px;
  font-size: 22px;
  font-weight: 800;
  display: flex;
  align-items: center;
  gap: 12px;
}

.ads-zone {
  padding: 18px;
  text-align: center;
  border: 1px dashed rgba(255, 255, 255, 0.2);
  color: var(--muted);
  font-size: 14px;
  border-radius: var(--radius);
  background: rgba(0, 0, 0, 0.2);
}

.layout {
  display: grid;
  gap: 24px;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 320px);
  margin-bottom: 40px;
}

.sidebar {
  position: sticky;
  top: 110px;
  display: grid;
  gap: 20px;
  align-self: start;
}

footer {
  margin-top: 48px;
  padding: 32px 0;
}

.footer-grid {
  display: grid;
  gap: 24px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}

.footer-copy {
  text-align: center;
  color: var(--muted);
  margin-top: 24px;
}

.toggle-group {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.pill {
  background: var(--glass-strong);
  border: 1px solid var(--border);
  border-radius: 999px;
  padding: 8px 16px;
  font-size: 14px;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  cursor: pointer;
}

.article-header {
  padding: 24px;
  margin-bottom: 20px;
}

.article-body {
  padding: 24px;
  line-height: 1.9;
  font-size: 18px;
}

.article-body h2,
.article-body h3 {
  margin-top: 28px;
  font-weight: 800;
}

.article-body a {
  color: var(--secondary);
  text-decoration: underline;
}

.language-switch {
  display: inline-flex;
  gap: 10px;
  align-items: center;
}

.translate-wrapper {
  background: var(--glass);
  border-radius: 999px;
  padding: 6px 12px;
  border: 1px solid var(--border);
  font-size: 12px;
}

.widget {
  padding: 20px;
}

.glow {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 20% 20%, rgba(122, 162, 255, 0.2), transparent 40%),
    radial-gradient(circle at 80% 10%, rgba(89, 240, 212, 0.2), transparent 40%),
    radial-gradient(circle at 50% 90%, rgba(255, 102, 196, 0.3), transparent 45%);
  opacity: 0.9;
  pointer-events: none;
}

@keyframes float {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-12px);
  }
}

@media (max-width: 980px) {
  .layout {
    grid-template-columns: 1fr;
  }
  .sidebar {
    position: static;
  }
}

@media (max-width: 720px) {
  header {
    position: static;
  }
  nav ul {
    gap: 10px;
  }
  .hero {
    padding: 32px 0 20px;
  }
  .toggle-group {
    justify-content: center;
  }
}

body.script:
(function () {
  const root = document.documentElement;
  const themeToggle = document.getElementById('themeToggle');
  const dirToggle = document.getElementById('dirToggle');
  const savedTheme = localStorage.getItem('theme') || 'dark';
  root.setAttribute('data-theme', savedTheme);
  themeToggle.addEventListener('click', () => {
    const next = root.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
    root.setAttribute('data-theme', next);
    localStorage.setItem('theme', next);
  });
  dirToggle.addEventListener('click', () => {
    const currentDir = document.body.getAttribute('dir') || 'rtl';
    const nextDir = currentDir === 'rtl' ? 'ltr' : 'rtl';
    document.body.setAttribute('dir', nextDir);
  });
})();

function googleTranslateElementInit() {
  new google.translate.TranslateElement({
    pageLanguage: 'ar',
    includedLanguages: 'ar,en',
    layout: google.translate.TranslateElement.InlineLayout.SIMPLE
  }, 'google_translate_element');
}
